$z=new ZipArchive();$z->open('public/templates/BA OPNAME FISIK PERSEDIAAN.docx');$xml=$z->getFromName('word/document.xml');$d=new DOMDocument();$d->loadXML($xml);$xp=new DOMXPath($d);$xp->registerNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$tbl=$xp->query('//w:tbl')->item(0);$rows=$xp->query('./w:tr',$tbl);foreach([0,1,2,3,4,57,58,90] as $i){$r=$rows->item($i);$cells=$xp->query('./w:tc',$r);echo "$i cells ".$cells->length." texts ";for($j=0;$j<$cells->length;$j++){echo '['.trim($xp->evaluate('string(.//w:t)',$cells->item($j))).']';}echo "\n";}
